-- PDT-414: a persona's empty tool list meant PDT's default set; now it means none. Each list saved empty becomes the
-- default set as it is today (pdt-core persona::DEFAULT_TOOLS), so those personas keep their tools.
UPDATE persona_versions SET tools = '["get_ticket","submit_outcome","ask_user","add_ticket_comment","add_review_comment","list_secrets","request_secret","run_with_secrets","write_secret_file","change_request_view","change_request_comment","change_request_open","change_request_merge","ci_runs","ci_failed_logs","issue_view","issue_comment","documents_list","document_get","doc_read","doc_edit","sheet_read","sheet_edit","document_create","document_link","comments_list","comment_reply","comment_resolve","document_open_beside","issue_create"]' WHERE json_valid(tools) AND json_array_length(tools) = 0;
UPDATE personas SET builtin_template = json_set(builtin_template, '$.tools', json('["get_ticket","submit_outcome","ask_user","add_ticket_comment","add_review_comment","list_secrets","request_secret","run_with_secrets","write_secret_file","change_request_view","change_request_comment","change_request_open","change_request_merge","ci_runs","ci_failed_logs","issue_view","issue_comment","documents_list","document_get","doc_read","doc_edit","sheet_read","sheet_edit","document_create","document_link","comments_list","comment_reply","comment_resolve","document_open_beside","issue_create"]'))
WHERE builtin_template IS NOT NULL AND json_valid(builtin_template)
  AND json_array_length(json_extract(builtin_template, '$.tools')) = 0;
